import React, { useState, useEffect } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../components/ui/card";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import { Leaf, CheckCircle, XCircle, Loader } from "lucide-react";
import axios from "axios";
import { useAuth } from "../contexts/AuthContext";

const API = process.env.REACT_APP_BACKEND_URL || "http://localhost:5000";

const RegisterPage = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { login } = useAuth();

  const token = searchParams.get("token");

  const [invitationData, setInvitationData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    full_name: "",
  });
  const [submitting, setSubmitting] = useState(false);

  const verifyToken = async () => {
    try {
      const response = await axios.get(
        `${API}/api/invitations/${token}/verify`
      );
      setInvitationData(response.data);
      setFormData({ ...formData, email: response.data.email });
    } catch (err) {
      setError(err.response?.data?.detail || "Invitación inválida o expirada");
    } finally {
      setLoading(false);
    }
  };
  
  useEffect(() => {
    if (!token) {
      setError("No se proporcionó un token de invitación");
      setLoading(false);
      return;
    }

    verifyToken();
  }, [token]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);

    try {
      const response = await axios.post(`${API}/api/auth/register`, {
        ...formData,
        token,
      });

      login(response.data.user, response.data.access_token);
      navigate("/dashboard");
    } catch (err) {
      alert(err.response?.data?.detail || "Error al registrarse");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100 flex items-center justify-center">
        <div className="text-center">
          <Loader className="w-12 h-12 animate-spin text-green-600 mx-auto mb-4" />
          <p className="text-gray-600">Verificando invitación...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100 flex items-center justify-center p-4">
        <Card className="max-w-md w-full">
          <CardContent className="p-8 text-center">
            <XCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
            <h2 className="text-2xl font-bold text-gray-900 mb-2">
              Invitación Inválida
            </h2>
            <p className="text-gray-600 mb-6">{error}</p>
            <Button
              onClick={() => navigate("/")}
              className="bg-green-600 hover:bg-green-700"
            >
              Volver al Inicio
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100">
      {/* Header */}
      <header className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center space-x-4">
            <img
              src="https://customer-assets.emergentagent.com/job_cbf5d180-7dc8-49ac-bba7-d2fbaff8451a/artifacts/gmhdedz7_464681137_861366946106337_8408541761944089839_n.jpg"
              alt="EUREKA Logo"
              className="h-12 w-12 rounded-full"
            />
            <div>
              <h1 className="text-2xl font-bold text-gray-900">EUREKA</h1>
              <p className="text-sm text-green-600">
                Sistemas Integrados de Gestión
              </p>
            </div>
          </div>
        </div>
      </header>

      {/* Registration Form */}
      <div className="flex items-center justify-center py-12 px-4">
        <Card className="max-w-md w-full shadow-2xl">
          <CardHeader className="text-center">
            <CheckCircle className="w-12 h-12 text-green-600 mx-auto mb-2" />
            <CardTitle className="text-2xl">Completa tu Registro</CardTitle>
            <p className="text-sm text-gray-600 mt-2">
              Has sido invitado como{" "}
              <strong className="text-green-600">
                {invitationData?.role === "admin"
                  ? "Administrador"
                  : invitationData?.role === "user"
                  ? "Consultor"
                  : "Cliente"}
              </strong>
            </p>
            {invitationData?.client_name && (
              <p className="text-xs text-gray-500 mt-1">
                Empresa: {invitationData.client_name}
              </p>
            )}
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label htmlFor="full_name">Nombre Completo *</Label>
                <Input
                  id="full_name"
                  value={formData.full_name}
                  onChange={(e) =>
                    setFormData({ ...formData, full_name: e.target.value })
                  }
                  required
                  placeholder="Juan Pérez"
                />
              </div>

              <div>
                <Label htmlFor="email">Email *</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  readOnly
                  className="bg-gray-100"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Email asignado en la invitación
                </p>
              </div>

              <div>
                <Label htmlFor="password">Contraseña *</Label>
                <Input
                  id="password"
                  type="password"
                  value={formData.password}
                  onChange={(e) =>
                    setFormData({ ...formData, password: e.target.value })
                  }
                  required
                  minLength={6}
                  placeholder="Mínimo 6 caracteres"
                />
              </div>

              <Button
                type="submit"
                className="w-full bg-green-600 hover:bg-green-700"
                disabled={submitting}
              >
                {submitting ? "Registrando..." : "Completar Registro"}
              </Button>
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default RegisterPage;
